package dev.gyeopdam.embeddedtor;

import android.content.Context;
import android.system.Os;
import android.util.AtomicFile;
import dev.gyeopdam.embeddedtor.host.FakeAndroidKeyStoreProvider;
import java.io.File;
import java.io.IOException;
import java.nio.file.*;
import java.security.Security;
import java.util.*;
import java.util.stream.Stream;

/** Actual production checkpoint/envelope with Android storage doubles and synthetic capabilities only. */
public final class PendingDeviceRecoveryHostReview {
    static final String ORIGIN="http://"+"a".repeat(56)+".onion",OTHER="http://"+"b".repeat(56)+".onion",ACCOUNT="demo-account-a",TARGET="demo-device-lost";
    static final String OLD=capability(0);static int passed,assertions;
    interface Attempt{void run()throws Exception;}interface Scenario{void run(TestContext c)throws Exception;}
    public static void main(String[] args)throws Exception{
        if(args.length!=1||Security.getProvider("AndroidKeyStore")!=null)throw new AssertionError("ISOLATED_HOST_REQUIRED");
        FakeAndroidKeyStoreProvider provider=new FakeAndroidKeyStoreProvider();Security.addProvider(provider);
        try{schema();Path root=Path.of(args[0]);
            run(root,"read-only absence creates no key",c->{PendingDeviceRecoveryStore s=store(c);check(s.load()==null);s.acknowledge("demo-recovery-absent");check(FakeAndroidKeyStoreProvider.generations==0&&AtomicFile.completedCommits==0);});
            run(root,"durable prepare and exact retry preserve capabilities and ciphertext",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending p=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);check(!p.confirmed&&!p.replacementAccountToken.equals(OLD));check(SessionSchema.token(p.replacementAccountToken,"gd_acct_"));byte[] before=bytes(c);same(p,store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD));same(p,store(c).load());check(Arrays.equals(before,bytes(c)));check(AtomicFile.completedCommits==1&&FakeAndroidKeyStoreProvider.generations==1);String disk=new String(before,java.nio.charset.StandardCharsets.ISO_8859_1);check(!disk.contains(OLD)&&!disk.contains(p.replacementAccountToken)&&!disk.contains(ACCOUNT));check(p.toString().equals("PendingDeviceRecovery([redacted])"));});
            run(root,"conflicting origin account target or old capability never replaces checkpoint",c->{PendingDeviceRecoveryStore s=store(c);s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);byte[] before=bytes(c);reject(()->s.prepare(OTHER,ACCOUNT,TARGET,OLD),PendingDeviceRecoveryStore.Code.ORIGIN_MISMATCH);reject(()->s.prepare(ORIGIN,"demo-other",TARGET,OLD),PendingDeviceRecoveryStore.Code.PENDING_CONFLICT);reject(()->s.prepare(ORIGIN,ACCOUNT,"demo-other-target",OLD),PendingDeviceRecoveryStore.Code.PENDING_CONFLICT);reject(()->s.prepare(ORIGIN,ACCOUNT,TARGET,capability(1)),PendingDeviceRecoveryStore.Code.PENDING_CONFLICT);check(Arrays.equals(before,bytes(c)));});
            run(root,"unconfirmed or mismatched acknowledgement cannot discard capabilities",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending p=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);byte[] before=bytes(c);reject(()->s.acknowledge(p.recoveryId),PendingDeviceRecoveryStore.Code.UNCONFIRMED);reject(()->s.markConfirmed("demo-other"),PendingDeviceRecoveryStore.Code.STATE_CHANGED);check(Arrays.equals(before,bytes(c)));});
            run(root,"confirmed phase survives recreation and exact confirm is no-op",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending p=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);PendingDeviceRecoveryStore.Pending accepted=s.markConfirmed(p.recoveryId);check(accepted.confirmed);same(accepted,store(c).load());byte[] before=bytes(c);same(accepted,store(c).markConfirmed(p.recoveryId));check(Arrays.equals(before,bytes(c)));});
            run(root,"acknowledgement writes secret-free tombstone and a later attempt is fresh",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending p=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);s.markConfirmed(p.recoveryId);s.acknowledge(p.recoveryId);check(store(c).load()==null&&FakeAndroidKeyStoreProvider.keyCount()==1);byte[] plain=new KeystoreBlobStore(c,"device-recovery").read();check(PendingDeviceRecoverySchema.decode(plain).fields==null);PendingDeviceRecoveryStore.Pending next=s.prepare(ORIGIN,ACCOUNT,TARGET,p.replacementAccountToken);check(!p.recoveryId.equals(next.recoveryId)&&!p.replacementAccountToken.equals(next.replacementAccountToken));check(FakeAndroidKeyStoreProvider.generations==1);});
            run(root,"prepare CAS preserves concurrently created checkpoint",c->{c.race(()->store(c).prepare(ORIGIN,ACCOUNT,"demo-other-target",OLD));reject(()->store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD),PendingDeviceRecoveryStore.Code.IDENTITY_MISMATCH);check(store(c).load().targetDeviceId.equals("demo-other-target"));});
            run(root,"confirm CAS cannot mark a replaced checkpoint",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending p=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);c.race(()->{store(c).resetAfterConfirmation(store(c).load().recoveryId);store(c).prepare(ORIGIN,ACCOUNT,"demo-other-target",OLD);});reject(()->s.markConfirmed(p.recoveryId),PendingDeviceRecoveryStore.Code.IDENTITY_MISMATCH);check(!store(c).load().confirmed&&store(c).load().targetDeviceId.equals("demo-other-target"));});
            run(root,"acknowledge CAS cannot erase a replacement checkpoint",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending p=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);s.markConfirmed(p.recoveryId);c.race(()->{store(c).resetAfterConfirmation(store(c).load().recoveryId);store(c).prepare(ORIGIN,ACCOUNT,"demo-other-target",OLD);});reject(()->s.acknowledge(p.recoveryId),PendingDeviceRecoveryStore.Code.IDENTITY_MISMATCH);check(store(c).load().targetDeviceId.equals("demo-other-target"));});
            run(root,"uncertain prepare retains exact retry instead of regenerating",c->{AtomicFile.throwAfterReplacement=true;reject(()->store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD),PendingDeviceRecoveryStore.Code.IO_FAILED);AtomicFile.throwAfterReplacement=false;PendingDeviceRecoveryStore.Pending p=store(c).load();check(p!=null);byte[] before=bytes(c);same(p,store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD));check(Arrays.equals(before,bytes(c)));});
            run(root,"uncertain phase commit remains confirmed",c->{PendingDeviceRecoveryStore.Pending p=store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD);AtomicFile.throwAfterReplacement=true;reject(()->store(c).markConfirmed(p.recoveryId),PendingDeviceRecoveryStore.Code.IO_FAILED);AtomicFile.throwAfterReplacement=false;check(store(c).load().confirmed);});
            run(root,"uncertain acknowledgement remains a tombstone",c->{PendingDeviceRecoveryStore.Pending p=store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD);store(c).markConfirmed(p.recoveryId);AtomicFile.throwAfterReplacement=true;reject(()->store(c).acknowledge(p.recoveryId),PendingDeviceRecoveryStore.Code.IO_FAILED);AtomicFile.throwAfterReplacement=false;check(store(c).load()==null);store(c).acknowledge(p.recoveryId);});
            run(root,"corrupt ciphertext fails closed without overwrite",c->{PendingDeviceRecoveryStore.Pending p=store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD);byte[] damaged=bytes(c);damaged[damaged.length-1]^=1;Files.write(path(c),damaged);reject(()->store(c).load(),PendingDeviceRecoveryStore.Code.CORRUPT_STATE);reject(()->store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD),PendingDeviceRecoveryStore.Code.CORRUPT_STATE);reject(()->store(c).markConfirmed(p.recoveryId),PendingDeviceRecoveryStore.Code.CORRUPT_STATE);check(Arrays.equals(damaged,bytes(c)));});
            run(root,"missing key never regenerates over an existing checkpoint",c->{store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD);byte[] before=bytes(c);FakeAndroidKeyStoreProvider.reset();reject(()->store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD),PendingDeviceRecoveryStore.Code.KEY_UNAVAILABLE);check(FakeAndroidKeyStoreProvider.generations==0&&Arrays.equals(before,bytes(c)));});
            run(root,"read durability failure does not release pending capabilities",c->{store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD);AtomicFile.closeReadStreamAtEof=true;reject(()->store(c).load(),PendingDeviceRecoveryStore.Code.IO_FAILED);AtomicFile.closeReadStreamAtEof=false;check(store(c).load()!=null);});
            run(root,"stale readable abandonment preserves newer checkpoint",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending first=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);s.resetAfterConfirmation(first.recoveryId);PendingDeviceRecoveryStore.Pending next=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);reject(()->s.resetAfterConfirmation(first.recoveryId),PendingDeviceRecoveryStore.Code.STATE_CHANGED);check(s.load().recoveryId.equals(next.recoveryId));});
            run(root,"stale corruption approval preserves readable checkpoint",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending p=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);reject(()->s.resetAfterConfirmation(null),PendingDeviceRecoveryStore.Code.STATE_CHANGED);check(s.load().recoveryId.equals(p.recoveryId));});
            run(root,"abandon CAS cannot erase a concurrent replacement",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending p=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);c.race(()->{store(c).resetAfterConfirmation(p.recoveryId);store(c).prepare(ORIGIN,ACCOUNT,"demo-other-target",OLD);});reject(()->s.resetAfterConfirmation(p.recoveryId),PendingDeviceRecoveryStore.Code.IDENTITY_MISMATCH);check(store(c).load().targetDeviceId.equals("demo-other-target"));});
            run(root,"dispatch reservation rejects stale mutation epoch",c->{PendingDeviceRecoveryStore s=store(c);PendingDeviceRecoveryStore.Pending p=s.prepare(ORIGIN,ACCOUNT,TARGET,OLD);long epoch=PendingDeviceRecoveryStore.mutationEpoch();boolean[] dispatched={false};check(PendingDeviceRecoveryStore.dispatchIfCurrent(epoch,()->dispatched[0]=true)&&dispatched[0]);s.resetAfterConfirmation(p.recoveryId);dispatched[0]=false;check(!PendingDeviceRecoveryStore.dispatchIfCurrent(epoch,()->dispatched[0]=true)&&!dispatched[0]);});
            run(root,"recovery namespace has4KiB cap and separate AAD",c->{store(c).prepare(ORIGIN,ACCOUNT,TARGET,OLD);KeystoreBlobStore session=new KeystoreBlobStore(c,"session");byte[] other="synthetic other namespace".getBytes(java.nio.charset.StandardCharsets.US_ASCII);session.write(other);store(c).resetAfterConfirmation(store(c).load().recoveryId);check(store(c).load()==null&&Arrays.equals(other,session.read()));boolean bounded=false;try{new KeystoreBlobStore(c,"device-recovery").write(new byte[4097]);}catch(KeystoreBlobStore.StorageException expected){bounded=expected.code==KeystoreBlobStore.Code.INVALID_INPUT;}check(bounded);});
            run(root,"invalid input creates no key",c->{reject(()->store(c).prepare(ORIGIN,ACCOUNT,TARGET,"gd_acct_"+"B".repeat(43)),PendingDeviceRecoveryStore.Code.INVALID_INPUT);check(FakeAndroidKeyStoreProvider.generations==0);});
            System.out.println("PASS: "+assertions+" recovery schema/assertion checks; "+passed+" production checkpoint host scenarios");
            System.out.println("DOUBLES: Context, AtomicFile, Os, AndroidKeyStore; synthetic capabilities/keys only. No Android or network execution.");
        }finally{FakeAndroidKeyStoreProvider.reset();if(Security.getProvider("AndroidKeyStore")==provider)Security.removeProvider("AndroidKeyStore");}
    }
    static void schema()throws Exception{String[] fields={ORIGIN,ACCOUNT,TARGET,"demo-recovery-fixed",OLD,capability(1)};byte[] valid=PendingDeviceRecoverySchema.encode(fields,false);check(Arrays.equals(fields,PendingDeviceRecoverySchema.decode(valid).fields));check(!PendingDeviceRecoverySchema.decode(valid).confirmed);check(PendingDeviceRecoverySchema.decode(PendingDeviceRecoverySchema.encode(fields,true)).confirmed);check(PendingDeviceRecoverySchema.decode(PendingDeviceRecoverySchema.encode(null,false)).fields==null);
        for(int length=0;length<valid.length;length++){byte[] partial=Arrays.copyOf(valid,length);schemaReject(()->PendingDeviceRecoverySchema.decode(partial));}
        schemaReject(()->PendingDeviceRecoverySchema.decode(Arrays.copyOf(valid,valid.length+1)));byte[] phase=valid.clone();phase[11]=3;schemaReject(()->PendingDeviceRecoverySchema.decode(phase));String[] same=fields.clone();same[5]=same[4];schemaReject(()->PendingDeviceRecoverySchema.encode(same,false));String[] bad=fields.clone();bad[0]=ORIGIN+"/";schemaReject(()->PendingDeviceRecoverySchema.encode(bad,false));schemaReject(()->PendingDeviceRecoverySchema.encode(null,true));
    }
    static void schemaReject(Attempt a)throws Exception{boolean rejected=false;try{a.run();}catch(IOException|IllegalArgumentException expected){rejected=true;}check(rejected);}
    static PendingDeviceRecoveryStore store(TestContext c){return new PendingDeviceRecoveryStore(c);}static Path path(TestContext c){return c.directory.resolve("tortalk-device-recovery-v1.enc");}static byte[] bytes(TestContext c)throws Exception{return Files.readAllBytes(path(c));}
    static String capability(int value){byte[] bytes=new byte[32];Arrays.fill(bytes,(byte)value);return "gd_acct_"+Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
    static void same(PendingDeviceRecoveryStore.Pending a,PendingDeviceRecoveryStore.Pending b){check(b!=null&&a.serverOnion.equals(b.serverOnion)&&a.accountId.equals(b.accountId)&&a.targetDeviceId.equals(b.targetDeviceId)&&a.recoveryId.equals(b.recoveryId)&&a.oldAccountToken.equals(b.oldAccountToken)&&a.replacementAccountToken.equals(b.replacementAccountToken)&&a.confirmed==b.confirmed);}
    static void reject(Attempt a,PendingDeviceRecoveryStore.Code code)throws Exception{boolean rejected=false;try{a.run();}catch(PendingDeviceRecoveryStore.RecoveryException expected){rejected=expected.code==code&&expected.getCause()==null&&expected.getMessage().equals(code.name());}check(rejected);}
    static void check(boolean value){assertions++;if(!value)throw new AssertionError("RECOVERY_INVARIANT");}
    static void run(Path root,String name,Scenario action)throws Exception{AtomicFile.reset();Os.reset();FakeAndroidKeyStoreProvider.reset();Path directory=Files.createTempDirectory(root,"recovery-");try{action.run(new TestContext(directory));check(Os.openDescriptorCount()==0);passed++;System.out.println("PASS "+name);}finally{FakeAndroidKeyStoreProvider.reset();try(Stream<Path> paths=Files.walk(directory)){for(Path p:paths.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.deleteIfExists(p);}}}
    static final class TestContext extends Context{final Path directory;int remaining;Attempt race;TestContext(Path p){directory=p;}void race(Attempt a){race=a;remaining=2;}public Context getApplicationContext(){return this;}public String getPackageName(){return "dev.gyeopdam.embeddedtor.recoveryhost";}public File getNoBackupFilesDir(){if(race!=null&&--remaining==0){Attempt a=race;race=null;try{a.run();}catch(Exception e){throw new AssertionError("RACE_FIXTURE",e);}}return directory.toFile();}}
}
